function floorAt(x,z){
  const bx=Math.round(x),bz=Math.round(z);let highest=-4;
  for(let y=14;y>=-4;y--){
    const type=blocks.get(key(bx,y,bz));
    if(type==='grass'||type==='dirt'||type==='stone'){highest=y;break;}
  }
  return highest+.5;
}

